using ModelContextProtocol.Server;
using System.Text.Json;

namespace McpHttpServer;

[McpServerResource(
    UriTemplate = "config://app/settings",
    Name = "AppSettings",
    Description = "Returns the current application configuration data")]
public class ConfigResource
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["environment"] = "production",
        ["version"] = "1.0.0",
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["betaFeatures"] = false,
            ["notifications"] = true
        },
        ["maxRetries"] = 3,
        ["timeoutSeconds"] = 30
    };

    public static ReadResourceResult Read()
    {
        var json = JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions
        {
            WriteIndented = true
        });

        return new ReadResourceResult
        {
            Contents =
            [
                new TextResourceContents
                {
                    Uri = "config://app/settings",
                    MimeType = "application/json",
                    Text = json
                }
            ]
        };
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class GreetingTool
{
    [McpServerTool(Name = "greet"), Description("Greets a user by name")]
    public static string Greet(
        [Description("The name to greet")] string name)
    {
        return $"Hello, {name}! Welcome to the MCP HTTP server.";
    }
}

